#!/usr/bin/env bash
# Builds an iOS project generated by `engine ios-project` (macOS + Xcode) into
# an unsigned .ipa, which Sideloadly or AltStore sign with the user's Apple ID
# when installing:
#   - WebView shell (project.yml): XcodeGen → xcodebuild without code signing;
#   - Flutter project (pubspec.yaml): flutter build ios --no-codesign.
#
# Usage: ios-build.sh <project-dir> <out-dir> <ipa-file-name>     # device .ipa
#        ios-build.sh <project-dir> <out-dir> - simulator         # .app for the iOS Simulator
set -euo pipefail
project="$1"; out="$2"; ipa="$3"; mode="${4:-device}"
mkdir -p "$out"
out=$(cd "$out" && pwd)
cd "$project"

if [ -f pubspec.yaml ]; then
  command -v flutter > /dev/null || { echo "::error::Flutter SDK is not installed"; exit 1; }
  echo "flutter: $(flutter --version 2> /dev/null | sed -n 1p), $(xcodebuild -version 2> /dev/null | sed -n 1p)"
  if [ "$mode" = simulator ]; then
    sdk=iphonesimulator; args=(--simulator --debug)
  else
    sdk=iphoneos; args=(--release --no-codesign)
  fi
  if ! flutter build ios "${args[@]}" > "$out/flutter-$sdk.log" 2>&1; then
    grep -E "Error|error:|Failed" "$out/flutter-$sdk.log" | head -40 || true
    tail -40 "$out/flutter-$sdk.log"
    if grep -q "Development Team" "$out/flutter-$sdk.log"; then
      echo "Примечание: подсказку Flutter про Development Team можно не выполнять — .ipa собирается без подписи"
      echo "(её подписывает Sideloadly). Причина ошибки — в строках Error / error выше."
    fi
    exit 1
  fi
  app="build/ios/$sdk/Runner.app"
else
  if ! command -v xcodegen > /dev/null; then
    HOMEBREW_NO_AUTO_UPDATE=1 HOMEBREW_NO_INSTALL_CLEANUP=1 brew install xcodegen > /dev/null
  fi
  xcodegen generate --quiet
  if [ "$mode" = simulator ]; then
    sdk=iphonesimulator; arch_args=(ARCHS=arm64 ONLY_ACTIVE_ARCH=NO)
  else
    sdk=iphoneos; arch_args=(ARCHS=arm64)
  fi
  echo "xcodebuild: $sdk, $(xcodebuild -version 2> /dev/null | sed -n 1p)"
  if ! xcodebuild -project App.xcodeproj -target App -configuration Release -sdk "$sdk" \
      SYMROOT="$PWD/build" "${arch_args[@]}" \
      CODE_SIGNING_ALLOWED=NO CODE_SIGNING_REQUIRED=NO CODE_SIGN_IDENTITY="" \
      build > "$out/xcodebuild-$sdk.log" 2>&1; then
    grep -E "error:|warning: .*(deprecated|unavailable)|BUILD FAILED" "$out/xcodebuild-$sdk.log" | head -40 || true
    tail -40 "$out/xcodebuild-$sdk.log"
    exit 1
  fi
  app="build/Release-$sdk/App.app"
fi

if [ "$mode" = simulator ]; then
  name=$(basename "$app")
  rm -rf "${out:?}/$name" && cp -R "$app" "$out/"
  echo "Simulator app: $out/$name"
  exit 0
fi

rm -rf Payload && mkdir Payload && cp -R "$app" Payload/
rm -f "$out/$ipa"
zip -qry "$out/$ipa" Payload
rm -rf Payload
echo "IPA: $out/$ipa ($(du -h "$out/$ipa" | cut -f1))"
